// Normalize a RevenueCat v1 event into a Revenue-tab row.
const crypto = require('crypto');
const ev = $('RevenueCat Webhook').item.json.body?.event || {};
const cfg = $('Config').item.json;
const type = ev.type || 'UNKNOWN';
const product = ev.product_id || '';
const store = ev.store || 'Other';
const priceUSD = (ev.price_in_purchased_currency != null) ? ev.price_in_purchased_currency : (ev.price || 0);

// Map RC event type -> our Event Type label.
const MAP = { INITIAL_PURCHASE:'Initial Purchase', RENEWAL:'Renewal', CANCELLATION:'Cancellation', UNCANCELLATION:'Renewal', NON_RENEWING_PURCHASE:'Message Pack', EXPIRATION:'Cancellation', PRODUCT_CHANGE:'Renewal', BILLING_ISSUE:'Cancellation', TRIAL_STARTED:'Trial Start', TRIAL_CONVERTED:'Trial Conversion', REFUND:'Refund' };
const eventType = MAP[type] || type;

// MRR delta: monthly subs add ~price/1, annual add price/12. Cancellations subtract.
const monthlyEq = (id) => { if(/year|annual/i.test(id)) return (parseFloat(cfg.PRICE_ANNUAL)||0)/12; if(/month/i.test(id)) return parseFloat(cfg.PRICE_MONTHLY)||0; return 0; };
let mrrDelta = 0;
if (['Initial Purchase','Trial Conversion'].includes(eventType)) mrrDelta = monthlyEq(product);
else if (['Cancellation','Refund'].includes(eventType)) mrrDelta = -monthlyEq(product);

// Hash the app user id — never store raw.
const rawId = ev.app_user_id || ev.original_app_user_id || '';
const hashed = rawId ? crypto.createHash('sha256').update(String(rawId)).digest('hex').slice(0,16) : '';

const milestone = ['Initial Purchase','Trial Conversion'].includes(eventType);
return [{ json: {
  date: new Date().toISOString().slice(0,10),
  eventType, product, store,
  amount: Number(priceUSD)||0,
  currency: ev.currency || 'USD',
  hashed, mrrDelta: Math.round(mrrDelta*100)/100,
  sheetId: cfg.SHEET_ID, alertUrl: cfg.ALERT_WEBHOOK_URL, milestone
} }];
